export function wrapVariableDeclarator(
	data: T.VariableDeclarator & { readonly $other?: T.VariableDeclarator | readonly T.VariableDeclarator[] },
	tree: TreeHandle
): T.VariableDeclarator.Parsed {
	if (typeof data === 'number') return data as unknown as T.VariableDeclarator.Parsed;
	const node = modelSlots(data, ['_variable_declarator_plain', '_variable_declarator_definite']);
	const kindKeyed = _firstKindKeyedWrapChild(node, ['variable_declarator_plain', 'variable_declarator_definite']) as
		| T.VariableDeclarator
		| readonly T.VariableDeclarator[]
		| undefined;
	const filtered =
		kindKeyed ?? _filterWrapChildrenByKind(node.$other, ['variable_declarator_plain', 'variable_declarator_definite']);
	if (
		filtered === undefined &&
		(typeof (node as _UntypedNode).$text === 'string' || treeHandleOf(node) !== undefined)
	) {
		return hydrateSelf<T.VariableDeclarator>(
			node as T.VariableDeclarator,
			tree
		) as unknown as T.VariableDeclarator.Parsed;
	}
	return hydrateChild<T.VariableDeclarator>(
		normalizeSingularWrapSlot(filtered, 'children', true, node.$type, {
			tree,
			nodeType: node.$type,
			slotName: 'children',
			span: (node as _UntypedNode).$span
		}),
		tree
	);
}

