export function wrapPattern(
	data: T.Pattern & { readonly $other?: T.Pattern | readonly T.Pattern[] },
	tree: TreeHandle
): T.Pattern.Parsed {
	if (typeof data === 'number') return data as unknown as T.Pattern.Parsed;
	const node = modelSlots(data, ['__lhs_expression', '_lhs_expression', '_rest_pattern']);
	const kindKeyed = _firstKindKeyedWrapChild(node, ['_lhs_expression', 'lhs_expression', 'rest_pattern']) as
		| T.Pattern
		| readonly T.Pattern[]
		| undefined;
	const filtered =
		kindKeyed ?? _filterWrapChildrenByKind(node.$other, ['_lhs_expression', 'lhs_expression', 'rest_pattern']);
	if (
		filtered === undefined &&
		(typeof (node as _UntypedNode).$text === 'string' || treeHandleOf(node) !== undefined)
	) {
		return hydrateSelf<T.Pattern>(node as T.Pattern, tree) as unknown as T.Pattern.Parsed;
	}
	return hydrateChild<T.Pattern>(
		normalizeSingularWrapSlot(filtered, 'children', true, node.$type, {
			tree,
			nodeType: node.$type,
			slotName: 'children',
			span: (node as _UntypedNode).$span
		}),
		tree
	);
}

