export function wrapIndexSignature(
	data: T.IndexSignature & { readonly $other?: T.IndexSignature | readonly T.IndexSignature[] },
	tree: TreeHandle
): T.IndexSignature.Parsed {
	if (typeof data === 'number') return data as unknown as T.IndexSignature.Parsed;
	const node = modelSlots(data, ['_index_signature_colon', '_index_signature_mapped_type_clause']);
	const kindKeyed = _firstKindKeyedWrapChild(node, ['index_signature_colon', 'index_signature_mapped_type_clause']) as
		| T.IndexSignature
		| readonly T.IndexSignature[]
		| undefined;
	const filtered =
		kindKeyed ??
		_filterWrapChildrenByKind(node.$other, ['index_signature_colon', 'index_signature_mapped_type_clause']);
	if (
		filtered === undefined &&
		(typeof (node as _UntypedNode).$text === 'string' || treeHandleOf(node) !== undefined)
	) {
		return hydrateSelf<T.IndexSignature>(node as T.IndexSignature, tree) as unknown as T.IndexSignature.Parsed;
	}
	return hydrateChild<T.IndexSignature>(
		normalizeSingularWrapSlot(filtered, 'children', true, node.$type, {
			tree,
			nodeType: node.$type,
			slotName: 'children',
			span: (node as _UntypedNode).$span
		}),
		tree
	);
}

