		$type: envelope,
		$source: shown.$source,
		$named: shown.$named,
		$span: shown.$span,
		$handle: shown.$handle,
		$parentHandle: shown.$parentHandle,
		$treeHandle: shown.$treeHandle,
		$childIndex: shown.$childIndex,
